import bisect

class TemplateError(Exception):
    def __init__(self, message, line=0):
        super().__init__(message)
        self.line = line

class _Undefined:
    __slots__ = ()
UNDEFINED = _Undefined()

WHITESPACE_CHARS = " \t\n"
RESERVED_KEYWORDS = {"and", "or", "not", "true", "false", "none", "in"}
BLOCK_NAMES = {"if", "elif", "else", "endif", "for", "endfor", "set"}
ZERO_FILTERS = {"upper", "lower", "trim", "length", "first", "last", "raw"}
ONE_FILTERS = {"join", "truncate", "default"}


class Token:
    __slots__ = ("kind", "value", "raw")

    def __init__(self, kind, value, raw=None):
        self.kind = kind
        self.value = value
        self.raw = raw


class NumNode:
    __slots__ = ("value",)
    def __init__(self, value):
        self.value = value


class ConstNode:
    __slots__ = ("value",)
    def __init__(self, value):
        self.value = value


class StrNode:
    __slots__ = ("value",)
    def __init__(self, value):
        self.value = value


class PathNode:
    __slots__ = ("name", "segments")
    def __init__(self, name, segments):
        self.name = name
        self.segments = segments


class NotNode:
    __slots__ = ("child",)
    def __init__(self, child):
        self.child = child


class CmpNode:
    __slots__ = ("left", "op", "right")
    def __init__(self, left, op, right):
        self.left = left
        self.op = op
        self.right = right


class OrNode:
    __slots__ = ("left", "right")
    def __init__(self, left, right):
        self.left = left
        self.right = right


class AndNode:
    __slots__ = ("left", "right")
    def __init__(self, left, right):
        self.left = left
        self.right = right


class FilterChainNode:
    __slots__ = ("value", "filters")
    def __init__(self, value, filters):
        self.value = value
        self.filters = filters


class ParenNode:
    __slots__ = ("child",)
    def __init__(self, child):
        self.child = child


class TextNode:
    __slots__ = ("text",)
    def __init__(self, text):
        self.text = text


class OutputNode:
    __slots__ = ("expr", "raw")
    def __init__(self, expr, raw):
        self.expr = expr
        self.raw = raw


class IfNode:
    __slots__ = ("branches", "else_body")
    def __init__(self):
        self.branches = []
        self.else_body = None


class ForNode:
    __slots__ = ("name", "expr", "body", "else_body")
    def __init__(self, name, expr):
        self.name = name
        self.expr = expr
        self.body = []
        self.else_body = None


class SetNode:
    __slots__ = ("name", "expr")
    def __init__(self, name, expr):
        self.name = name
        self.expr = expr


def _is_ident_start(c):
    return c == "_" or "a" <= c <= "z" or "A" <= c <= "Z"


def _is_ident_char(c):
    return c == "_" or "a" <= c <= "z" or "A" <= c <= "Z" or "0" <= c <= "9"


def _is_digit(c):
    return "0" <= c <= "9"


def _line_starts(template):
    starts = [0]
    for i, ch in enumerate(template):
        if ch == "\n":
            starts.append(i + 1)
    return starts


def tokenize(content, line):
    tokens = []
    i = 0
    n = len(content)
    while i < n:
        c = content[i]
        if c.isspace():
            i += 1
            continue
        if c == "-":
            if i + 1 < n and _is_digit(content[i + 1]):
                j = i + 1
                while j < n and _is_digit(content[j]):
                    j += 1
                raw = content[i:j]
                tokens.append(Token("num", int(raw), raw))
                i = j
            else:
                raise TemplateError("invalid '-'", line)
        elif _is_digit(c):
            j = i
            while j < n and _is_digit(content[j]):
                j += 1
            raw = content[i:j]
            tokens.append(Token("num", int(raw), raw))
            i = j
        elif _is_ident_start(c):
            j = i
            while j < n and _is_ident_char(content[j]):
                j += 1
            tokens.append(Token("name", content[i:j], None))
            i = j
        elif c == "=":
            if i + 1 < n and content[i + 1] == "=":
                tokens.append(Token("op", "==", "=="))
                i += 2
            else:
                tokens.append(Token("op", "=", "="))
                i += 1
        elif c == "!":
            if i + 1 < n and content[i + 1] == "=":
                tokens.append(Token("op", "!=", "!="))
                i += 2
            else:
                raise TemplateError("invalid '!' ", line)
        elif c in ".|()":
            tokens.append(Token("op", c, c))
            i += 1
        elif c == '"' or c == "'":
            j = i + 1
            while j < n and content[j] != c:
                j += 1
            if j == n:
                raise TemplateError("unterminated string", line)
            tokens.append(Token("str", content[i + 1:j], None))
            i = j + 1
        else:
            raise TemplateError("invalid character", line)
    return tokens


class ExprParser:
    def __init__(self, tokens, line, pos=0):
        self.tokens = tokens
        self.line = line
        self.pos = pos

    def error(self, msg):
        raise TemplateError(msg, self.line)

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def peek_is(self, kind, value=None):
        tok = self.peek()
        if tok is None or tok.kind != kind:
            return False
        return value is None or tok.value == value

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        node = self.parse_or()
        if self.pos != len(self.tokens):
            self.error("unexpected token")
        return node

    def parse_or(self):
        left = self.parse_and()
        while self.peek_is("name", "or"):
            self.advance()
            right = self.parse_and()
            left = OrNode(left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.peek_is("name", "and"):
            self.advance()
            right = self.parse_not()
            left = AndNode(left, right)
        return left

    def parse_not(self):
        if self.peek_is("name", "not"):
            self.advance()
            return NotNode(self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_filter_chain()
        if self.peek_is("op", "==") or self.peek_is("op", "!="):
            op = self.advance().value
            right = self.parse_filter_chain()
            if self.peek_is("op", "==") or self.peek_is("op", "!="):
                self.error("chained comparison")
            return CmpNode(left, op, right)
        return left

    def parse_filter_chain(self):
        value = self.parse_primary()
        filters = []
        while self.peek_is("op", "|"):
            self.advance()
            if not self.peek_is("name"):
                self.error("filter name expected")
            fname = self.advance().value
            if fname in ZERO_FILTERS:
                if self.peek_is("op", "("):
                    self.error("filter takes no arguments")
                filters.append((fname, None))
            elif fname in ONE_FILTERS:
                if not self.peek_is("op", "("):
                    self.error("filter requires an argument")
                self.advance()
                arg = self.parse_or()
                if not self.peek_is("op", ")"):
                    self.error(") expected")
                self.advance()
                filters.append((fname, arg))
            else:
                self.error("unknown filter")
        if filters:
            return FilterChainNode(value, filters)
        return value

    def parse_primary(self):
        tok = self.peek()
        if tok is None:
            self.error("unexpected end of expression")
        if tok.kind == "num":
            self.advance()
            return NumNode(tok.value)
        if tok.kind == "str":
            self.advance()
            return StrNode(tok.value)
        if tok.kind == "name":
            val = tok.value
            if val == "true":
                self.advance()
                return ConstNode(True)
            if val == "false":
                self.advance()
                return ConstNode(False)
            if val == "none":
                self.advance()
                return ConstNode(None)
            if val in ("and", "or", "not", "in"):
                self.error("keyword cannot be a path name")
            return self.parse_path()
        if tok.kind == "op" and tok.value == "(":
            self.advance()
            inner = self.parse_or()
            if not self.peek_is("op", ")"):
                self.error(") expected")
            self.advance()
            return ParenNode(inner)
        self.error("unexpected token")

    def parse_path(self):
        name_tok = self.advance()
        segments = []
        while self.peek_is("op", "."):
            self.advance()
            seg_tok = self.peek()
            if seg_tok is None:
                self.error("expected path segment")
            if seg_tok.kind == "name":
                if seg_tok.value in RESERVED_KEYWORDS:
                    self.error("keyword cannot be a path segment")
                segments.append(seg_tok.value)
                self.advance()
            elif seg_tok.kind == "num" and seg_tok.raw is not None and seg_tok.raw.isdigit():
                segments.append(seg_tok.raw)
                self.advance()
            else:
                self.error("invalid path segment")
        return PathNode(name_tok.value, segments)


def parse_expression(tokens, line, start=0):
    return ExprParser(tokens, line, start).parse()


def has_raw(node):
    return isinstance(node, FilterChainNode) and any(name == "raw" for name, _ in node.filters)


class TemplateParser:
    def __init__(self, parts):
        self.parts = parts
        self.pos = 0
        self.current = []
        self.stack = []

    def parse(self):
        while self.pos < len(self.parts):
            part = self.parts[self.pos]
            self.pos += 1
            if part[0] == "text":
                self.current.append(TextNode(part[1]))
            else:
                kind = part[1]
                content = part[2]
                line = part[5]
                if kind == "expr":
                    tokens = tokenize(content, line)
                    expr = parse_expression(tokens, line)
                    self.current.append(OutputNode(expr, has_raw(expr)))
                elif kind == "comment":
                    continue
                else:
                    self.handle_block(content, line)
        if self.stack:
            raise TemplateError("unclosed block", self.stack[-1]["line"])
        return self.current

    def push(self, typ, node, line):
        self.stack.append({
            "type": typ,
            "node": node,
            "else_seen": False,
            "line": line,
            "prev": self.current,
        })

    def top_if(self, line):
        if not self.stack or self.stack[-1]["type"] != "if":
            raise TemplateError("endif does not fit", line)
        return self.stack[-1]

    def top_for(self, line):
        if not self.stack or self.stack[-1]["type"] != "for":
            raise TemplateError("endfor does not fit", line)
        return self.stack[-1]

    def top_else_capable(self, line):
        if not self.stack:
            raise TemplateError("else does not fit", line)
        entry = self.stack[-1]
        if entry["type"] not in ("if", "for"):
            raise TemplateError("else does not fit", line)
        return entry

    def handle_block(self, content, line):
        tokens = tokenize(content, line)
        if not tokens:
            raise TemplateError("empty block tag", line)
        first = tokens[0]
        if first.kind != "name" or first.value not in BLOCK_NAMES:
            raise TemplateError("unknown block tag", line)
        name = first.value

        if name == "set":
            if len(tokens) < 3:
                raise TemplateError("set requires name and expression", line)
            name_tok = tokens[1]
            if name_tok.kind != "name" or name_tok.value in RESERVED_KEYWORDS:
                raise TemplateError("invalid set name", line)
            if tokens[2].kind != "op" or tokens[2].value != "=":
                raise TemplateError("set requires '='", line)
            expr = parse_expression(tokens, line, 3)
            self.current.append(SetNode(name_tok.value, expr))

        elif name == "if":
            expr = parse_expression(tokens, line, 1)
            node = IfNode()
            node.branches.append((expr, []))
            self.current.append(node)
            self.push("if", node, line)
            self.current = node.branches[-1][1]

        elif name == "elif":
            entry = self.top_if(line)
            if entry["else_seen"]:
                raise TemplateError("elif after else", line)
            expr = parse_expression(tokens, line, 1)
            entry["node"].branches.append((expr, []))
            self.current = entry["node"].branches[-1][1]

        elif name == "else":
            if len(tokens) > 1:
                raise TemplateError("else has extra tokens", line)
            entry = self.top_else_capable(line)
            if entry["else_seen"]:
                raise TemplateError("second else", line)
            entry["else_seen"] = True
            entry["node"].else_body = []
            self.current = entry["node"].else_body

        elif name == "endif":
            if len(tokens) > 1:
                raise TemplateError("endif has extra tokens", line)
            entry = self.top_if(line)
            self.current = entry["prev"]
            self.stack.pop()

        elif name == "endfor":
            if len(tokens) > 1:
                raise TemplateError("endfor has extra tokens", line)
            entry = self.top_for(line)
            self.current = entry["prev"]
            self.stack.pop()

        elif name == "for":
            if len(tokens) < 4:
                raise TemplateError("for requires name and expression", line)
            name_tok = tokens[1]
            if name_tok.kind != "name" or name_tok.value in RESERVED_KEYWORDS:
                raise TemplateError("invalid for name", line)
            if tokens[2].kind != "name" or tokens[2].value != "in":
                raise TemplateError("for requires 'in'", line)
            expr = parse_expression(tokens, line, 3)
            node = ForNode(name_tok.value, expr)
            self.current.append(node)
            self.push("for", node, line)
            self.current = node.body


